import React from "react";
import { useState } from "react";
import { Tooltip, Grow } from "@mui/material";
import { watchlist } from "../data/data";
import WatchListItem from "./WatchListItem";

const WatchList = () => {
  return (
    <div className="container">
      <div className="row">
        <div className="col-8" style={{ width: "20rem" }}>
          <div className="watchlist-container">
            <div className="search-container">
              <input
                type="text"
                name="search"
                id="search"
                placeholder="Search eg:infy, bse, nifty fut weekly, gold mcx"
                className="search"
              />
              <span className="counts"> {watchlist.length} / 50</span>
            </div>

            <ul className="list">
              {watchlist.map((stock, index) => {
                return (
                  <WatchListItem stock={stock} key={index}></WatchListItem>
                );
              })}
            </ul>
          </div>
        </div>
        <div className="col-1">
          <div className="container">
            <div className="row">
              <div className="coloumn">
                <form>
                  <input
                    style={{
                      width: "7rem",
                      height: "2rem",
                      marginBottom: "2rem",
                      marginLeft: "1rem",
                    }}
                  ></input>
                </form>
                <p
                  className="fs-6"
                  style={{ fontSize: "0.7rem", marginLeft: "1rem" }}
                >
                  <b className="fs-6">Margin required $140.65</b>
                </p>
              </div>
              <div className="coloumn">
                {" "}
                <form>
                  <input
                    style={{
                      width: "7rem",
                      height: "2rem",
                      marginBottom: "1.3rem",
                      marginLeft: "1rem",
                    }}
                    className="p-4"
                  ></input>
                </form>
                <button
                  style={{
                    height: "1.5rem",
                    width: "3rem",
                    backgroundColor: "skyblue",
                  }}
                >
                  Buy
                </button>
                <button
                  style={{
                    height: "1.5rem",
                    width: "4rem",
                  }}
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default WatchList;
